node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Get ALL flights with full details
const flights = db.prepare('SELECT * FROM flights WHERE status = \"scheduled\"').all();

// Parse each flight's dates and prices
const parsed = flights.map(f => ({
  ...f,
  cabin_prices: JSON.parse(f.cabin_prices_json),
  dates: JSON.parse(f.dates_json)
}));

// Find all one-stop connections: flight A -> flight B where A.destination == B.origin
// and they share at least one date (or B departs on same/later date with enough layover)
const oneStopPairs = [];

for (const f1 of parsed) {
  for (const f2 of parsed) {
    if (f1.flight_id === f2.flight_id) continue;
    if (f1.destination !== f2.origin) continue;
    if (f1.origin === f2.destination) continue; // skip trivial round trips to same place

    // Check date compatibility
    const f1Dates = Object.keys(f1.dates);
    const f2Dates = Object.keys(f2.dates);

    for (const d1 of f1Dates) {
      for (const d2 of f2Dates) {
        if (d2 >= d1) { // f2 departs on same day or later
          // Check if f2 departs after f1 arrives (need some layover)
          // Parse times
          let f1Arr = f1.arrival_time;
          let f2Dep = f2.departure_time;

          // Normalize times for comparison
          const getTime = (t, date) => {
            if (t.includes('T')) return t;
            return date + 'T' + t;
          };

          const arr = getTime(f1Arr, d1);
          const dep = getTime(f2Dep, d2);

          if (dep > arr || d2 > d1) {
            // Check both flights are available on their respective dates
            if (f1.dates[d1]?.status === 'available' && f2.dates[d2]?.status === 'available') {
              oneStopPairs.push({
                leg1: {
                  flight_id: f1.flight_id,
                  origin: f1.origin,
                  destination: f1.destination,
                  departure: getTime(f1.departure_time, d1),
                  arrival: arr,
                  date: d1,
                  cabin_prices: f1.dates[d1].prices || f1.cabin_prices,
                  source_skill: f1.source_skill
                },
                leg2: {
                  flight_id: f2.flight_id,
                  origin: f2.origin,
                  destination: f2.destination,
                  departure: dep,
                  arrival: getTime(f2.arrival_time, d2),
                  date: d2,
                  cabin_prices: f2.dates[d2].prices || f2.cabin_prices,
                  source_skill: f2.source_skill
                },
                route: f1.origin + ' → ' + f1.destination + ' → ' + f2.destination,
                total_prices: {}
              });
            }
          }
        }
      }
    }
  }
}

// Calculate combined prices for common cabin classes
oneStopPairs.forEach(pair => {
  const classes1 = Object.keys(pair.leg1.cabin_prices);
  const classes2 = Object.keys(pair.leg2.cabin_prices);
  const common = classes1.filter(c => classes2.includes(c));
  common.forEach(c => {
    pair.total_prices[c] = pair.leg1.cabin_prices[c] + pair.leg2.cabin_prices[c];
  });
});

console.log('Total one-stop flight pairs found:', oneStopPairs.length);
console.log('');

// Group by route for readability
const byRoute = {};
oneStopPairs.forEach(p => {
  const key = p.route;
  if (!byRoute[key]) byRoute[key] = [];
  byRoute[key].push(p);
});

Object.keys(byRoute).sort().forEach(route => {
  console.log('=== Route: ' + route + ' (' + byRoute[route].length + ' options) ===');
  byRoute[route].forEach((p, i) => {
    console.log('  Option ' + (i+1) + ':');
    console.log('    Leg 1: ' + p.leg1.flight_id + ' | ' + p.leg1.origin + '→' + p.leg1.destination + ' | Depart: ' + p.leg1.departure + ' | Arrive: ' + p.leg1.arrival + ' | Date: ' + p.leg1.date);
    console.log('    Leg 2: ' + p.leg2.flight_id + ' | ' + p.leg2.origin + '→' + p.leg2.destination + ' | Depart: ' + p.leg2.departure + ' | Arrive: ' + p.leg2.arrival + ' | Date: ' + p.leg2.date);
    console.log('    Combined Prices: ' + JSON.stringify(p.total_prices));
    console.log('');
  });
});

// Also save full JSON for the output file
const fs = require('fs');
fs.writeFileSync('/tmp/onestop_raw.json', JSON.stringify(oneStopPairs, null, 2));
console.log('Raw data saved to /tmp/onestop_raw.json');
" 2>&1

